package com.trampolim.api.education;

import java.util.*;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class LibraryService {
    private final JdbcTemplate jdbc;private final LearningAccess access;private final LearningController learning;
    @Value("${capacita.library.quota-bytes:536870912}")private long quota=536870912;
    public LibraryService(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,LearningController learning){this.jdbc=jdbc;this.access=access;this.learning=learning;}
    public record MaterialInput(long courseId,Long subjectId,Long moduleId,String title,String description,String topic,String category,String alternativeText,String accessScope,boolean allowDownload,String status,List<Long> lessonIds,Integer revision){}
    public List<Map<String,Object>> list(String email,boolean manage,Long course,Long subject,Long module,Long lesson,String search,String category,Long teacher,Long before){
        var user=access.account(email);if(manage&&!user.teacher())deny();var args=new ArrayList<Object>();String where=" WHERE d.status<>'DELETED'";
        if(manage){if(!user.admin()){where+=" AND c.teacher_id=?";args.add(user.id());}}
        else where+=" AND d.status='PUBLISHED' AND d.access_scope='STUDENTS' AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND u.account_status='ACTIVE'";
        if(course!=null){where+=" AND d.course_id=?";args.add(course);}if(subject!=null){where+=" AND d.subject_id=?";args.add(subject);}if(module!=null){where+=" AND d.module_id=?";args.add(module);}
        if(lesson!=null){learning.visibleLesson(user,lesson,manage);where+=" AND (EXISTS(SELECT 1 FROM learning_material_lessons link WHERE link.material_id=d.id AND link.lesson_id=?) OR (NOT EXISTS(SELECT 1 FROM learning_material_lessons link WHERE link.material_id=d.id) AND (d.module_id=(SELECT module_id FROM learning_lessons WHERE id=?) OR (d.module_id IS NULL AND (d.subject_id=(SELECT m.subject_id FROM learning_lessons l JOIN learning_modules m ON m.id=l.module_id WHERE l.id=?) OR d.subject_id IS NULL)))))";args.add(lesson);args.add(lesson);args.add(lesson);where+=" AND d.course_id=?";args.add(access.courseForLesson(lesson));}
        if(search!=null&&!search.isBlank()){String term=bounded(search,180);where+=" AND (d.title ILIKE ? ESCAPE '!' OR d.topic ILIKE ? ESCAPE '!')";String pattern="%"+term.replace("!","!!").replace("%","!%").replace("_","!_")+"%";args.add(pattern);args.add(pattern);}
        if(category!=null&&!category.isBlank()){where+=" AND d.category=?";args.add(bounded(category,100));}if(teacher!=null){where+=" AND d.teacher_id=?";args.add(teacher);}if(before!=null){where+=" AND d.id<?";args.add(before);}
        return jdbc.queryForList(summary()+where+" ORDER BY d.id DESC LIMIT 50",args.toArray());
    }
    public Map<String,Object> detail(String email,long id,boolean manage){var user=access.account(email);visible(user,id,manage);var result=jdbc.queryForMap(summary()+" WHERE d.id=?",id);result.put("lesson_ids",jdbc.queryForList("SELECT lesson_id FROM learning_material_lessons WHERE material_id=? ORDER BY lesson_id",Long.class,id));if(manage)result.put("versions",jdbc.queryForList("SELECT id,version_number,size_bytes,page_count,has_text,tagged,created_at FROM learning_material_versions WHERE material_id=? ORDER BY version_number DESC",id));return result;}
    @Transactional("capacitaTransactionManager") public Map<String,Object> create(String email,MaterialInput input){var user=access.teacher(email);validate(user,input);if(!"DRAFT".equals(input.status()))bad("Crie um rascunho e valide o PDF antes de publicar.");long id=jdbc.queryForObject("INSERT INTO learning_materials(course_id,subject_id,module_id,teacher_id,title,description,topic,category,alternative_text,access_scope,allow_download) VALUES (?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,input.courseId(),input.subjectId(),input.moduleId(),courseTeacher(input.courseId()),input.title().trim(),bounded(input.description(),4000),bounded(input.topic(),180),bounded(input.category(),100),bounded(input.alternativeText(),100000),input.accessScope(),input.allowDownload());links(id,input.lessonIds());audit(user.id(),id,"CREATED");return Map.of("id",id);}
    @Transactional("capacitaTransactionManager") public void edit(String email,long id,MaterialInput input){var user=access.teacher(email);var row=lock(id);visible(user,id,true);validate(user,input);if(((Number)row.get("course_id")).longValue()!=input.courseId())bad("Não é possível mover o material para outro curso.");if(input.revision()==null||input.revision()!=((Number)row.get("revision")).intValue())throw new ResponseStatusException(HttpStatus.CONFLICT,"O material foi alterado. Reabra-o antes de salvar.");if("PUBLISHED".equals(input.status())&&row.get("current_version_id")==null)bad("Envie e valide o PDF antes da publicação.");jdbc.update("UPDATE learning_materials SET subject_id=?,module_id=?,title=?,description=?,topic=?,category=?,alternative_text=?,access_scope=?,allow_download=?,status=?,published_at=CASE WHEN ?='PUBLISHED' THEN COALESCE(published_at,CURRENT_TIMESTAMP) ELSE published_at END,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.subjectId(),input.moduleId(),input.title().trim(),bounded(input.description(),4000),bounded(input.topic(),180),bounded(input.category(),100),bounded(input.alternativeText(),100000),input.accessScope(),input.allowDownload(),input.status(),input.status(),id);links(id,input.lessonIds());audit(user.id(),id,"UPDATED_"+input.status());}
    @Transactional("capacitaTransactionManager") public Map<String,Object> install(String email,long id,LibraryPdfStore.Stored stored,int revision){var user=access.teacher(email);var row=lock(id);visible(user,id,true);if(revision!=((Number)row.get("revision")).intValue())throw new ResponseStatusException(HttpStatus.CONFLICT,"O material mudou durante o envio. Reabra-o antes de atualizar.");jdbc.queryForObject("SELECT id FROM student_users WHERE id=? FOR NO KEY UPDATE",Long.class,courseTeacher(((Number)row.get("course_id")).longValue()));Long existing=jdbc.queryForList("SELECT id FROM learning_material_versions WHERE material_id=? AND sha256=?",Long.class,id,stored.sha256()).stream().findFirst().orElse(null);if(existing!=null)return Map.of("id",existing,"duplicate",true);
        long used=jdbc.queryForObject("SELECT COALESCE(sum(v.size_bytes),0) FROM learning_material_versions v JOIN learning_materials d ON d.id=v.material_id WHERE d.teacher_id=?",Long.class,courseTeacher(((Number)row.get("course_id")).longValue()));if(used+stored.bytes()>quota)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Limite de armazenamento de PDFs atingido.");
        int number=jdbc.queryForObject("SELECT COALESCE(max(version_number),0)+1 FROM learning_material_versions WHERE material_id=?",Integer.class,id);long version=jdbc.queryForObject("INSERT INTO learning_material_versions(material_id,version_number,storage_key,sha256,size_bytes,page_count,has_text,tagged,uploaded_by) VALUES (?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,id,number,stored.key(),stored.sha256(),stored.bytes(),stored.pages(),stored.hasText(),stored.tagged(),user.id());jdbc.update("UPDATE learning_materials SET current_version_id=?,status='DRAFT',revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",version,id);audit(user.id(),id,"VERSION_UPLOADED");return Map.of("id",version,"duplicate",false);}
    @Transactional("capacitaTransactionManager")public void delete(String email,long id){var user=access.teacher(email);lock(id);visible(user,id,true);jdbc.update("UPDATE learning_materials SET status='DELETED',deleted_at=CURRENT_TIMESTAMP,revision=revision+1 WHERE id=?",id);audit(user.id(),id,"DELETED");}
    public Map<String,Object> version(String email,long id,Long version,boolean download){var user=access.account(email);var row=jdbc.queryForList("SELECT * FROM learning_materials WHERE id=? AND status<>'DELETED'",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));boolean manager=user.teacher()&&(user.admin()||courseTeacher(((Number)row.get("course_id")).longValue())==user.id());visible(user,id,manager);if(download&&!manager&&!Boolean.TRUE.equals(row.get("allow_download")))deny();if(version!=null&&!manager)deny();Object selected=version==null?row.get("current_version_id"):version;if(selected==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);var file=jdbc.queryForList("SELECT * FROM learning_material_versions WHERE material_id=? AND id=?",id,selected).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));file.put("title",row.get("title"));file.put("alternative_text",row.get("alternative_text"));return file;}
    @Transactional("capacitaTransactionManager")public void reserve(String email,long id){var user=access.teacher(email);visible(user,id,true);jdbc.update("INSERT INTO learning_library_uploads(user_id) VALUES (?) ON CONFLICT DO NOTHING",user.id());var row=jdbc.queryForMap("SELECT * FROM learning_library_uploads WHERE user_id=? FOR UPDATE",user.id());boolean reset=((java.sql.Timestamp)row.get("window_started_at")).toInstant().plusSeconds(3600).isBefore(java.time.Instant.now());int count=reset?0:((Number)row.get("attempts")).intValue();if(count>=12)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite de 12 envios de PDF por hora atingido.");jdbc.update("UPDATE learning_library_uploads SET attempts=?,window_started_at=CASE WHEN ? THEN CURRENT_TIMESTAMP ELSE window_started_at END WHERE user_id=?",count+1,reset,user.id());}
    private void visible(LearningAccess.Account user,long id,boolean manage){var row=jdbc.queryForList("SELECT course_id,status,access_scope FROM learning_materials WHERE id=? AND status<>'DELETED'",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));long course=((Number)row.get("course_id")).longValue();if(manage){if(!user.teacher())deny();access.ownCourse(user,course);}else{learning.visibleCourse(user,course,false);if(!"PUBLISHED".equals(row.get("status"))||!"STUDENTS".equals(row.get("access_scope")))deny();}}
    private void validate(LearningAccess.Account user,MaterialInput input){if(input==null)bad("Informe os dados do material.");access.ownCourse(user,input.courseId());if(input.title()==null||input.title().isBlank())bad("Informe o título.");bounded(input.title(),180);bounded(input.description(),4000);bounded(input.topic(),180);bounded(input.category(),100);bounded(input.alternativeText(),100000);if(!Set.of("DRAFT","PUBLISHED","HIDDEN").contains(Objects.toString(input.status(),""))||!Set.of("STUDENTS","TEACHERS").contains(Objects.toString(input.accessScope(),"")))bad("Situação ou permissão inválida.");if(input.subjectId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_subjects WHERE id=? AND course_id=?)",Boolean.class,input.subjectId(),input.courseId())))bad("Disciplina de outro curso.");if(input.moduleId()!=null){if(access.courseForModule(input.moduleId())!=input.courseId())bad("Módulo de outro curso.");if(input.subjectId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_modules WHERE id=? AND subject_id=?)",Boolean.class,input.moduleId(),input.subjectId())))bad("Módulo fora da disciplina.");}if(input.lessonIds()!=null){if(input.lessonIds().size()>100||input.lessonIds().stream().anyMatch(Objects::isNull)||new HashSet<>(input.lessonIds()).size()!=input.lessonIds().size())bad("Seleção de aulas inválida.");for(Long lesson:input.lessonIds()){if(access.courseForLesson(lesson)!=input.courseId())bad("Aula de outro curso.");if(input.moduleId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_lessons WHERE id=? AND module_id=?)",Boolean.class,lesson,input.moduleId())))bad("Aula fora do módulo.");if(input.subjectId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_lessons l JOIN learning_modules m ON m.id=l.module_id WHERE l.id=? AND m.subject_id=?)",Boolean.class,lesson,input.subjectId())))bad("Aula fora da disciplina.");}}}
    private Map<String,Object> lock(long id){return jdbc.queryForList("SELECT * FROM learning_materials WHERE id=? AND status<>'DELETED' FOR UPDATE",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
    private long courseTeacher(long course){return jdbc.queryForObject("SELECT teacher_id FROM learning_courses WHERE id=?",Long.class,course);}
    private void links(long id,List<Long> lessons){jdbc.update("DELETE FROM learning_material_lessons WHERE material_id=?",id);if(lessons!=null)for(Long lesson:lessons)jdbc.update("INSERT INTO learning_material_lessons(material_id,lesson_id) VALUES (?,?)",id,lesson);}
    private void audit(long actor,long material,String event){jdbc.update("INSERT INTO learning_library_audit(actor_id,material_id,event) VALUES (?,?,?)",actor,material,event);}
    private static String summary(){return "SELECT d.*,u.full_name AS teacher_name,c.title AS course_title,s.title AS subject_title,m.title AS module_title,v.version_number,v.page_count,v.size_bytes,v.has_text,v.tagged FROM learning_materials d JOIN learning_courses c ON c.id=d.course_id JOIN student_users u ON u.id=c.teacher_id LEFT JOIN learning_subjects s ON s.id=d.subject_id LEFT JOIN learning_modules m ON m.id=d.module_id LEFT JOIN learning_material_versions v ON v.id=d.current_version_id";}
    private static String bounded(String value,int max){if(value==null)return "";if(value.length()>max)bad("Um campo excede o limite permitido.");return value.trim();}
    private static void bad(String message){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static void deny(){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Material não autorizado.");}
}
